def algorithm(func, dim, lb, ub, budget, rng):
    n = len(rng)
    x_best = np.array([ub + rng[i]*(ub - lb) for i in range(n)])
    f_best = func(x_best)

    T = 10.0
    alpha = 0.99

    for _ in range(budget):
        for i in range(n):
            sigma = rng[i] * (ub - lb)
            x_new = np.array([x_best[j] + sigma * (2 * rng[j] - 1) if j == i else x_best[j] for j in range(n)])
            f_new = func(x_new)

            if f_new < f_best or rng[i] < np.exp(-(f_new - f_best)/T):
                x_best = x_new
                f_best = f_new

        T *= alpha

    return np.clip(x_best, lb, ub)

def algorithm(func, dim, lb, ub, budget, rng):
    def clip(x):
        return np.clip(x, a_min=lb, a_max=ub)

    x = np.random.uniform(lb, ub, size=(dim,))
    best_x = x.copy()
    best_f = func(x)

    for _ in range(budget):
        new_x = x + rng.randn(dim,)
        new_x = clip(new_x)

        res = minimize(lambda x: func(clip(x)), new_x, method='SLSQP', bounds=[(lb, ub)]*dim, constraints=())

        if res.fun < best_f:
            best_f = res.fun
            best_x = res.x

    return np.array(best_x)

